const S = {"ALT": {"type": "object", "properties": {"found": {"type": "boolean"}, "rules": {"type": "string"}, "reading": {"type": "string"}}, "required": ["found", "rules", "reading"]}, "D": {"type": "object", "properties": {"answer": {"type": "string"}, "program": {"type": "string"}, "runs": {"type": "integer"}}, "required": ["answer", "program", "runs"]}, "C": {"type": "object", "properties": {"answer": {"type": "string"}, "program": {"type": "string"}, "runs": {"type": "integer"}, "changed": {"type": "boolean"}}, "required": ["answer", "program", "runs", "changed"]}}
phase('Ход')
const out = {}
const th = TEAM.map(t => async () => { const s = await agent(t.solver, {label: t.id + '|team1', phase: 'Ход', schema: S.D}); out[t.id + '|team1'] = s;
  const c = await agent(t.c1 + String(s ? s.answer : '') + t.c2 + String(s ? s.program : '') + t.c3, {label: t.id + '|chk', phase: 'Ход', schema: S.C}); out[t.id + '|chk'] = c })
const jh = JOBS.map(j => async () => { out[j.id] = await agent(j.prompt, {label: j.id, phase: 'Ход', schema: S[j.schema]}) })
await parallel([...th, ...jh])
return {out}
